 fn render_bytes_with_css(
     batch: *const c_uchar,
     len: u32,
     root: u32,
     fragment: bool,
     debug: bool,
     css_base: Option<&str>,
 ) -> *const c_char {
     if batch.is_null() {
         return std::ptr::null();
     }
     let bytes = unsafe { std::slice::from_raw_parts(batch, len as usize) };
     let (opcodes, strings) = match decode_frame(bytes) {
         Ok(decoded) => decoded,
         Err(_) => return std::ptr::null(),
     };
     let renderer = HtmlRenderer::new().with_debug_comments(debug);
     let html = if fragment {
         renderer.render_fragment(&opcodes, &strings, root)
     } else if let Some(base) = css_base {
         renderer.render_document_linked(&opcodes, &strings, root, base)
     } else {
         renderer.render_document(&opcodes, &strings, root)
     };
     match CString::new(html) {
         Ok(cs) => cs.into_raw(),
         Err(_) => std::ptr::null(),
     }
 }

