         // supplies the default size/weight; explicit `FONT_SIZE`/`FONT_WEIGHT`
         // below override it (raw modifiers layer on top).
         if let Some(style) = self.text_style_code() {
             if let Some((size, weight)) = text_style_scale(style) {
