         assert!(css.contains(".pathland-spinner"), "spinner component");
         assert!(css.contains(".pathland-gauge"), "gauge component");
         // Dark mode media query.
         assert!(css.contains("prefers-color-scheme: dark"), "dark mode");
         // System font stack (no external font loading; the family resolves to
         // the platform's UI font).
         assert!(css.contains("font-feature-settings: 'liga' 1, 'calt' 1"), "Chrome ligature fix");
         assert!(css.contains("--pl-font-body-family: system-ui, -apple-system"), "system font stack");
         assert!(!css.contains("Inter"), "no bundled/external font family");
         // Document background + input field styling (Tailwind-style inset outline).
         assert!(css.contains("--pl-color-background"), "page background token");
         assert!(css.contains("color-scheme: light dark"), "native form controls follow the theme");
         assert!(css.contains(".pathland-input"), "input component");
         assert!(css.contains("--pl-input-border"), "input border token");
         assert!(css.contains("outline: var(--pl-control-border-width) solid var(--pl-input-border)"), "inset outline instead of border");
         assert!(css.contains("outline-offset: calc(-1 * var(--pl-control-border-width))"), "inset ring");
         assert!(css.contains("--pl-input-focus"), "input focus token");
         // Native controls inherit the preflight + design-token surface.
         for selector in [
             ".pathland-control",
             ".pathland-select",
             ".pathland-date",
             ".pathland-color",
             ".pathland-progress",
             ".pathland-video",
         ] {
             assert!(css.contains(selector), "native control selector {selector}");
         }
         assert!(css.contains("::-webkit-progress-value"), "native progress fill");
         assert!(css.contains("--pl-progress-fill"), "progress fill token");
         assert!(css.contains("accent-color: var(--pl-control-accent)"), "control accent inherited");
         // Range slider: custom track/fill/thumb, not native chrome.
         assert!(css.contains("::-webkit-slider-runnable-track"), "webkit range track");
         assert!(css.contains("::-webkit-slider-thumb"), "webkit range thumb");
         assert!(css.contains("::-moz-range-track"), "firefox range track");
         assert!(css.contains("::-moz-range-progress"), "firefox range fill");
         assert!(css.contains("::-moz-range-thumb"), "firefox range thumb");
         assert!(css.contains("var(--pl-slider-fill)"), "range fill variable");
         assert!(css.contains("--pl-slider-track"), "range track token");
         assert!(css.contains("--pl-slider-thumb"), "range thumb token");
     }

     #[test]
     fn linked_document_emits_a_cacheable_base_stylesheet_link() {
         let renderer = HtmlRenderer::new();
         let name = css::builtin_css_name();
         assert!(name.starts_with("base-"), "content-hashed name: {name}");
         assert!(name.ends_with(".css"), "css asset name: {name}");

         let linked = renderer.render_document_linked(&[], &[], 0, "/_pathland");
         assert!(
             linked.contains(&format!(
                 "<link rel=\"stylesheet\" href=\"/_pathland/{name}\">"
             )),
             "linked stylesheet: {linked}"
         );
         assert!(!linked.contains("<style>"), "base CSS is not inlined: {linked}");
         assert!(!linked.contains("--pl-color-primary:"), "no inline base tokens: {linked}");

         // A trailing slash is normalized, and the default render stays inline.
         let mounted = renderer.render_document_linked(&[], &[], 0, "/app2/_pathland/");
         assert!(
             mounted.contains(&format!(
                 "<link rel=\"stylesheet\" href=\"/app2/_pathland/{name}\">"
             )),
             "mounted base: {mounted}"
         );
         let inline = renderer.render_document(&[], &[], 0);
         assert!(inline.contains("<style>"), "default remains inline");
         assert!(inline.contains("--pl-color-primary:"), "default carries the tokens");

         // An empty base is a graceful fallback to the inline document.
         let fallback = renderer.render_document_linked(&[], &[], 0, "  ");
         assert!(fallback.contains("<style>"), "empty base falls back inline");
     }

     #[test]
     fn builtin_css_covers_tier1_default_tokens() {
         let css = css::STYLE;
         // Generative spacing base — without it `space.<N>` refs resolve to an
         // undefined variable unless the app overrides `space.base`.
         assert!(css.contains("--pl-space-base"), "space.base token");
         assert_eq!(count(css, "--pl-space-base"), 3, "space.base has light + dark (platform + forced) defaults");
         // Canonical typography tokens (spec/TOKENS.md font.body.*).
         for var in [
             "--pl-font-body-size",
             "--pl-font-body-weight",
             "--pl-font-body-family",
         ] {
             assert!(css.contains(var), "missing {var}");
         }
         // Canonical control/button/input + per-component tokens so app
         // overrides retheme components.
         for var in [
             "--pl-toggle-accent",
             "--pl-slider-accent",
             "--pl-progress-fill",
             "--pl-gauge-fill",
             "--pl-control-background",
             "--pl-control-foreground",
             "--pl-control-border",
             "--pl-control-border-width",
             "--pl-control-radius",
             "--pl-control-height",
             "--pl-control-accent",
             "--pl-button-background",
             "--pl-button-background-hover",
             "--pl-button-foreground",
             "--pl-button-border",
             "--pl-button-radius",
             "--pl-button-padding-horizontal",
             "--pl-button-padding-vertical",
             "--pl-button-font-size",
             "--pl-button-font-weight",
             "--pl-input-background",
             "--pl-input-foreground",
             "--pl-input-placeholder",
             "--pl-input-border",
             "--pl-input-radius",
             "--pl-input-font-size",
         ] {
             assert!(css.contains(var), "missing canonical token {var}");
         }
         // Radius scale + hairline border width (Tier 1).
         for var in [
             "--pl-radius-xs",
             "--pl-radius-sm",
             "--pl-radius-md",
             "--pl-radius-lg",
             "--pl-radius-xl",
             "--pl-radius-full",
             "--pl-border-width-thin",
         ] {
             assert!(css.contains(var), "missing {var}");
         }
         // Elevation (composite shadows) — the shadow-sm replacement.
         for var in [
             "--pl-elevation-low-color",
             "--pl-elevation-low-x",
             "--pl-elevation-low-y",
             "--pl-elevation-low-blur",
             "--pl-elevation-high-color",
         ] {
             assert!(css.contains(var), "missing {var}");
         }
         assert!(!css.contains("--pl-color-focus-ring"), "focus ring now maps to control.accent");
         assert!(!css.contains("--pl-button-bg"), "internal button vars mapped onto button.*");
         assert!(!css.contains("--pl-shadow-sm"), "shadow-sm mapped onto elevation.low.*");
     }

