/// Render a self-contained PLPL batch as an **HTML fragment** with **debug
/// comments** on every node (a non-zero `debug` enables them). Ownership and
/// safety as [`pathland_html_render`].
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render_fragment_debug(
    batch: *const c_uchar,
    len: u32,
    root: u32,
    debug: u8,
) -> *const c_char {
    render_bytes(batch, len, root, true, debug != 0)
}

/// Release a string returned by [`pathland_html_render`] /
/// [`pathland_html_render_fragment`]. No-op on NULL.
///
/// # Safety
/// `ptr` must be a pointer previously returned by this module (or NULL).
#[no_mangle]
pub unsafe extern "C" fn pathland_html_free(ptr: *const c_char) {
    if !ptr.is_null() {
        drop(CString::from_raw(ptr as *mut c_char));
    }
}

/// Render a self-contained PLPL batch as a **full HTML document** whose base
/// design is a content-hashed stylesheet link at `{css_base}/{name}` instead of
/// an inline `<style>` block (see [`pathland_html_base_css_name`]). `debug`
/// non-zero enables node comments. Ownership and safety as
/// [`pathland_html_render`]; `css_base` must be a valid NUL-terminated C string
/// (or NULL, which falls back to the inline document).
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render_linked(
    batch: *const c_uchar,
    len: u32,
    root: u32,
    css_base: *const c_char,
    debug: u8,
) -> *const c_char {
    let css_base = if css_base.is_null() {
        None
    } else {
        match unsafe { CStr::from_ptr(css_base) }.to_str() {
            Ok(base) => Some(base),
            Err(_) => return std::ptr::null(),
        }
    };
    render_bytes_with_css(batch, len, root, false, debug != 0, css_base)
}

/// The generated base-design stylesheet (the bytes served at
/// `{base}/[`pathland_html_base_css_name`]`). Returns a NUL-terminated C string
/// owned by the caller (release with [`pathland_html_free`]).
#[no_mangle]
pub extern "C" fn pathland_html_base_css() -> *const c_char {
    match CString::new(css::builtin_css()) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
    }
}

/// The content-hashed asset name of the base stylesheet (e.g.
/// `base-5f86423db422.css`), so a host can serve it with immutable caching and
/// emit a cache-busting `<link>`. Returns a NUL-terminated C string owned by the
/// caller (release with [`pathland_html_free`]).
#[no_mangle]
pub extern "C" fn pathland_html_base_css_name() -> *const c_char {
    match CString::new(css::builtin_css_name()) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
    }
}

/// The full `<svg>` for a canonical `ICON_NAME` — the renderer-owned glyph
/// served at `/_pathland/icons/<name>.svg`. This is how every host language
/// (Java via JNA, Swift/.NET/Node/Go via this same ABI) serves the web
/// renderer's icon glyphs from ONE Rust source, instead of copying static
/// files per platform. Returns a NUL-terminated C string owned by the caller
/// (release with [`pathland_html_free`]); never NULL except when `name` is
/// NULL — an unknown/extension name yields this renderer's fallback glyph (the
/// same one SSR inlines), so a host can always answer with a glyph.
///
/// # Safety
/// `name` must be a valid NUL-terminated C string (or NULL).
#[no_mangle]
pub unsafe extern "C" fn pathland_html_icon_svg(name: *const c_char) -> *const c_char {
    if name.is_null() {
        return std::ptr::null();
    }
    let name = unsafe { CStr::from_ptr(name) }
        .to_string_lossy()
        .into_owned();
    let open = crate::icons::WEB_SVG_OPEN;
    let inner = crate::icons::web_inner(&name).unwrap_or_else(crate::icons::web_fallback_svg);
    let svg = format!("{open}{inner}</svg>");
    match CString::new(svg) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
    }
}

